head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.MSG_CHK_NEW = "데이터를 추가하려면 신규버튼을 누른 후 입력하세요.";
scwin.TR_JOB;
scwin.rowPos;
scwin.parentWin;
scwin.pIndex;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.parentWin = $c.frame.path("../");
        scwin.pIndex = scwin.parentWin.MaxTab_01.getSelectedTabIndex();
        $c.libRoundPanel.PanelToGroupBox(panel_Item);
        await scwin.listSync();

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제

        await scwin.setHeader();
        buttonSet.setInsertStatus();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35402.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_ISU_NM_onclick
 * @description img_ISU_NM 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_ISU_NM_onclick = async function() {
    try {
        if (dts_Item.getRowCount() === 0) {
            await $c.win.alert(scwin.MSG_CHK_NEW);
            return;
        }
        $c.stockSearch.JongmokSearch(txb_ISU_CD, txb_ISU_NM, SECUGRP_ID_ST, '2', 'A');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35402.img_ISU_NM_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35402.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_New_onclick = function() {
    try {
        buttonSet.setInsertStatus();
        scwin.initItem();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35402.btn_New_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35402.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        // alert(dts_List.NameValue(dts_List.RowPosition, "CORRCT_FACTR"));
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35402.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_OnFail
 * @description On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_OnFail = async function() {
    try {
        await $c.win.alert(dts_Item);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35402.trs_OnFail" });
    }
};

/**
 * @method
 * @name trs_OnSuccess
 * @description On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        await scwin.listSync();
        scwin.initItem();
        // alert('[TR_JOB]'+TR_JOB);
        if (scwin.TR_JOB === 'U') {
            dts_List.setRowPosition(scwin.rowPos, 0);
            scwin.openDetail(scwin.rowPos);
        } else {
            dts_List.setRowPosition(dts_List.getRowCount(), 0);
            scwin.openDetail(dts_List.getRowCount());
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35402.trs_OnSuccess" });
    }
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnClick = function(row, colid) {
    try {
        scwin.openDetail(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35402.grd_List_OnClick" });
    }
};

/**
 * @method
 * @name edt_CORRCT_FACTR_onkeydown
 * @description JACKAL_19.09.27
 * @param {*} keycode keycode
 * @param {*} skeycode skeycode
 * @returns {void}
 * @hidden N
 */
scwin.edt_CORRCT_FACTR_onkeydown = function(keycode, skeycode) {
    // JACKAL_19.09.27

    // if (dts_List.countRow == 0) {

    //    alert(MSG_CHK_NEW);

    //    edt_CORRCT_FACTR.text = "";

    // }

};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Item.insertRow();
};

/**
 * @method
 * @name listSync
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    // 조회
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/AdminAndDlstedDetection.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} gJobType gJobType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(gJobType) {
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    dts_Item.setCellData(1, "JOB_TYPE", gJobType);
    let vScrenProcTpCd;
    if (scwin.TR_JOB === "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB === "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB === "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    trs.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs",
        action : "/AdminAndDlstedDetection.do",
        ref : "dts_Item",
        target : "trs=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initItem
 * @description init Item 처리
 * @returns {void}
 * @hidden N
 */
scwin.initItem = function() {
    dts_Item.Reset();
    dts_Item.insertRow();
};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.openDetail = function(row) {
    dts_Item.setCellData(1, "ISU_CD", dts_List.getCellData(dts_List.getRowPosition(), "ISU_CD"));
    dts_Item.setCellData(1, "ISUR_CD", dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD"));
    dts_Item.setCellData(1, "COM_NM", dts_List.getCellData(dts_List.getRowPosition(), "COM_NM"));
    dts_Item.setCellData(1, "CORRCT_FACTR", dts_List.getCellData(dts_List.getRowPosition(), "CORRCT_FACTR"));
    dts_Item.setCellData(1, "ADJ_DD", dts_List.getCellData(dts_List.getRowPosition(), "ADJ_DD"));
    buttonSet.setUpdateStatus();
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    scwin.TR_JOB = 'I';
    await scwin.trs(TR_JOB_INSERT);
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    scwin.rowPos = dts_List.getRowPosition();
    await scwin.trs(TR_JOB_UPDATE);
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    scwin.TR_JOB = 'D';
    await scwin.trs(TR_JOB_DELETE);
};
